def compute(vars):
    start_value = vars["v1"]
    end_value = vars["v2"]
    if start_value == 0:
        return None
    return_value = (end_value - start_value) / start_value
    return {
        "value": return_value,
        "trace": {
            "start_value": start_value,
            "end_value": end_value,
            "return": return_value,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "return (decimal)"
            }
        }
    }
